#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int v; struct Node *l, *r; } Node;
static Node *mk(int v) { Node *n = malloc(sizeof(Node)); n->v = v; n->l = n->r = NULL; return n; }

int main(void) {
    Node *a = mk(1), *b = mk(2), *c = mk(3), *d = mk(4), *e = mk(5), *f = mk(6);
    a->l = b; a->r = c; b->l = d; b->r = e; c->r = f;

    Node *q[64]; int head = 0, tail = 0, level = 0;
    q[tail++] = a;
    while (head < tail) {
        int len = tail - head;              /* 锁定当前层节点数 */
        printf("第 %d 层:", level++);
        for (int i = 0; i < len; i++) {
            Node *n = q[head++];
            printf(" %d", n->v);
            if (n->l) q[tail++] = n->l;
            if (n->r) q[tail++] = n->r;
        }
        printf("\n");
    }
    return 0;
}
